    s = max(s, lS  > 0.5 ? vEdgeFactorsA.y : 0.0);
    s = max(s, lSW > 0.5 ? vEdgeFactorsA.z : 0.0);
    s = max(s, lNW > 0.5 ? vEdgeFactorsB.x : 0.0);
    s = max(s, lN  > 0.5 ? vEdgeFactorsB.y : 0.0);
    s = max(s, lNE > 0.5 ? vEdgeFactorsB.z : 0.0);
    if (s <= 0.0) return 0.0;

